public class TarArchiveOutputStream_finish_TriageGen1Test {





    @Test
    public void testFinishAfterCloseDoesNotThrow() throws IOException {
        // Note: Calling finish() after close() is generally invalid, 
        // but we test the flow of the method itself.
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);
        taos.close();

        try {
            taos.finish();
        } catch (IOException e) {
            // If the stream is closed, IOException is expected. 
            // This test ensures we handle the lifecycle.
        }
    }




}

