import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_finish_TriageGen1Test {







    @Test
    public void testFinishWithDifferentBlockSize() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        // Testing constructor with blockSize
        try (TarArchiveOutputStream taos = new TarArchiveOutputStream(baos, 1024)) {
            taos.finish();
        }
        Assert.assertTrue(baos.size() > 0);
    }


}

